/**
 * Unit tests for AbstractCommandLineRunner#doRun.
 */
public class AbstractCommandLineRunner_doRun_TriageGen2Test {

    // Mocking the generic types A and B for the abstract class
    private static class TestRunner extends AbstractCommandLineRunner<Compiler, CompilerOptions> {
        private final Compiler compiler;
        private final CompilerOptions options;
        private CommandLineConfig config;
        private OutputStream outStream;

        public TestRunner(Compiler compiler, CompilerOptions options, CommandLineConfig config) {
            this.compiler = compiler;
            this.options = options;
            this.config = config;
        }

        @Override
        protected Compiler createCompiler() { return compiler; }

        @Override
        protected CompilerOptions createOptions() { return options; }

        @Override
        protected CommandLineConfig getCommandLineConfig() { return config; }

        @Override
        protected List<JSSourceFile> createExterns() throws IOException { return Collections.emptyList(); }

        @Override
        protected List<JSSourceFile> createSourceInputs(List<String> jsFiles) { return Collections.emptyList(); }

        @Override
        protected List<JSModule> createJsModules(List<String> moduleSpecs, List<String> jsFiles) { return Collections.emptyList(); }

        @Override
        protected int processResults(Result result, List<JSModule> modules, CompilerOptions options) { return 0; }

        @Override
        protected void setRunOptions(CompilerOptions options) throws IOException {}

        @Override
        protected OutputStream fileNameToOutputWriter(String fileName) throws IOException { 
            return new ByteArrayOutputStream(); 
        }

        @Override
        protected OutputStream streamToOutputWriter(OutputStream out) { return out; }

        // Helper to inject 'out' via reflection if needed, but here we simulate via internal logic
        public void setOut(OutputStream out) { this.out = out; }

        // Since 'out' is protected in the base class, we use a spy/subclass approach
        // In a real scenario, we access the field via reflection if it's not accessible
    }

    // Dummy config class to match the usage in doRun
    static class CommandLineConfig {
        String loggingLevel = "INFO";
        List<String> js = new ArrayList<>();
        List<String> module = new ArrayList<>();
    }

    private Compiler mockCompiler;
    private CompilerOptions mockOptions;
    private CommandLineConfig config;
    private TestRunner runner;
    private ByteArrayOutputStream outputStream;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        mockCompiler = mock(Compiler.class);
        mockOptions = mock(CompilerOptions.class);
        config = new CommandLineConfig();
        mockOptions.jsOutputFile = "";

        runner = spy(new TestRunner(mockCompiler, mockOptions, config));
        outputStream = new ByteArrayOutputStream();
    }

    @Test
    public void testDoRun_StandardCompilation() throws Exception {
        config.js = Arrays.asList("file1.js");
        Result mockResult = mock(Result.class);
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        // Simulate 'out' being an OutputStream
        doReturn(outputStream).when(runner).fileNameToOutputWriter(any()); 
        // Note: The code uses 'out' which is a field in AbstractCommandLineRunner. 
        // We must ensure the runner's 'out' field is set or handled.

        // Because 'out' is a field in the parent class, we must set it via reflection
        java.lang.reflect.Field outField = AbstractCommandLineRunner.class.getDeclaredField("out");
        outField.setAccessible(true);
        outField.set(runner, outputStream);

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockCompiler).compile(any(), any(), any());
    }

    @Test
    public void testDoRun_ModuleCompilation() throws Exception {
        config.module = Arrays.asList("mod1.js");
        config.js = Arrays.asList("file1.js");
        Result mockResult = mock(Result.class);
        List<JSModule> mockModules = Collections.singletonList(mock(JSModule.class));

        when(mockCompiler.compileModules(any(), any(), any())).thenReturn(mockResult);
        doReturn(mockModules).when(runner).createJsModules(any(), any());

        java.lang.reflect.Field outField = AbstractCommandLineRunner.class.getDeclaredField("out");
        outField.setAccessible(true);
        outField.set(runner, outputStream);

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockCompiler).compileModules(any(), any(), any());
    }

    @Test
    public void testDoRun_WriteToFileBranch() throws Exception {
        config.js = Collections.singletonList("file1.js");
        mockOptions.jsOutputFile = "output.js";
        Result mockResult = mock(Result.class);
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        // Mocking fileNameToOutputWriter to return a Closeable writer
        Closeable mockWriter = mock(Closeable.class);
        doReturn(mockWriter).when(runner).fileNameToOutputWriter("output.js");

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockWriter).close();
    }

    @Test
    public void testDoRun_StreamToOutputWriterBranch() throws Exception {
        config.js = Collections.singletonList("file1.js");
        Result mockResult = mock(Result.class);
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        java.lang.reflect.Field outField = AbstractCommandLineRunner.class.getDeclaredField("out");
        outField.setAccessible(true);
        outField.set(runner, outputStream); // outputStream is an OutputStream

        doReturn(outputStream).when(runner).streamToOutputWriter(any());

        int result = runner.doRun();

        assertEquals(0, result);
        verify(runner).streamToOutputWriter(outputStream);
    }

    @Test
    public void testDoRun_ProcessResultsError() throws Exception {
        config.js = Collections.singletonList("file1.js");
        Result mockResult = mock(Result.class);
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);

        // Simulate error code from processResults
        doReturn(1).when(runner).processResults(any(), any(), any());

        java.lang.reflect.Field outField = AbstractCommandLineRunner.class.getDeclaredField("out");
        outField.setAccessible(true);
        outField.set(runner, outputStream);

        int result = runner.doRun();

        assertEquals(1, result);
    }
}
